import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n=data[0]
    vals=data[1:1+n]
    mx=max(vals, default=1)
    spf=list(range(mx+1))
    for i in range(2,int(mx**0.5)+1):
        if spf[i]==i:
            for j in range(i*i,mx+1,i):
                if spf[j]==j: spf[j]=i
    xor=0
    for a in vals:
        cnt=0
        while a>1:
            a//=spf[a]
            cnt+=1
        xor ^= cnt
    print('Anna' if xor else 'Bruno')

if __name__=='__main__': main()

