from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            starts[b].append((a, i))

        gains = [0] * m
        first_val = second_val = 0
        first_id = -1
        total = 0

        for right in range(1, n + 1):
            for a, idx in starts[right]:
                if a > first_val:
                    second_val, first_val = first_val, a
                    first_id = idx
                elif a > second_val:
                    second_val = a
            total += right - first_val
            if first_id != -1:
                gains[first_id] += first_val - second_val

        return total + max(gains)

