import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = [None] * (m + 1)
    for i in range(1, m + 1):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges[i] = (a, b, c)

    queries = []
    closed = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            i = next(it)
            queries.append((1, i))
            closed.add(i)
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges[1:], 1):
        if i not in closed:
            dist[a][b] = dist[b][a] = c

    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            value = dist[x][y]
            answers.append(-1 if value >= inf else value)
        else:
            a, b, c = edges[query[1]]
            col_a = [dist[i][a] for i in range(n)]
            col_b = [dist[i][b] for i in range(n)]
            row_a = dist[a][:]
            row_b = dist[b][:]
            for i in range(n):
                row_i = dist[i]
                via_a = col_a[i] + c
                via_b = col_b[i] + c
                for j in range(n):
                    candidate = min(via_a + row_b[j], via_b + row_a[j])
                    if candidate < row_i[j]:
                        row_i[j] = candidate

    sys.stdout.write('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

