    while size<n+1: size*=2
    mx=[-10**9]*(2*size); lazy=[0]*(2*size)
    def apply(v,d):
        mx[v]+=d; lazy[v]+=d
    def push(v):
        d=lazy[v]
        if d:
            apply(v*2,d); apply(v*2+1,d); lazy[v]=0
    def add(ql,qr,d,v=1,l=0,r=None):
        if r is None: r=size-1
        if ql<=l and r<=qr:
            apply(v,d); return
        push(v); m=(l+r)//2
        if ql<=m: add(ql,qr,d,v*2,l,m)
        if qr>m: add(ql,qr,d,v*2+1,m+1,r)
        mx[v]=max(mx[v*2],mx[v*2+1])
    def setval(pos,val,v=1,l=0,r=None):
        if r is None:r=size-1
        if l==r:
            mx[v]=val; lazy[v]=0; return
        push(v); m=(l+r)//2
        if pos<=m:setval(pos,val,v*2,l,m)
