class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Number of reductions for each possible population count.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps <= k - 1

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD

        ans = 0
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for c in range(1, n + 1):
                    if good[c]:
                        need = c - prefix
                        if 0 <= need <= rem:
                            ans += comb[rem][need]
                prefix += 1
        return ans % MOD

