def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,m=data[:2]
    rows=[0]*n; p=2
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1; p+=2
        rows[u]|=1<<v; rows[v]|=1<<u
    pivots=[]; r=0
    for c in range(n):
        k=next((i for i in range(r,n) if rows[i]>>c&1),None)
        if k is None: continue
        rows[r],rows[k]=rows[k],rows[r]
        for i in range(n):
            if i!=r and rows[i]>>c&1: rows[i]^=rows[r]
        pivots.append(c); r+=1
    free=[c for c in range(n) if c not in set(pivots)]
    ans=[0]*n
    for b,f in enumerate(free):
        vec=1<<f
        for i,c in enumerate(pivots):
            if rows[i]>>f&1: vec|=1<<c
        for v in range(n):
            if vec>>v&1: ans[v]|=1<<b
    if any(x==0 for x in ans): print('No')
    else:
        if m: ans=[x*4 for x in ans]
        print('Yes'); print(*ans)
