N = int(input())
# Let d = x-y. Then N = d*(3*y*y + 3*d*y + d*d), so d^3 <= N.
limit = int(round(N ** (1 / 3)))
while (limit + 1) ** 3 <= N:
    limit += 1
while limit ** 3 > N:
    limit -= 1

for d in range(1, limit + 1):
    if N % d:
        continue
    q = N // d
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s != disc or (s - 3 * d) % 6:
        continue
    y = (s - 3 * d) // 6
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

