from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(o, e, prev):
            length = o + e
            if length == 0:
                return 1
            first = 1 - prev
            need_o = (length + (1 if first == 1 else 0)) // 2
            need_e = length - need_o
            if need_o != o or need_e != e:
                return 0
            return fact[o] * fact[e]

        result = []
        prev = None
        while odds or evens:
            selected = None
            for x in sorted(odds + evens):
                p = x % 2
                if p == 1:
                    o, e = len(odds) - 1, len(evens)
                else:
                    o, e = len(odds), len(evens) - 1
                count = 0 if prev is not None and p == prev else completions(o, e, p)
                if k > count:
                    k -= count
                else:
                    selected = x
                    break
            if selected is None:
                return []
            result.append(selected)
            if selected % 2:
                odds.remove(selected)
            else:
                evens.remove(selected)
            prev = selected % 2
        return result

