class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        coeff = []
        for i in range(m):
            j = n - 1 - i
            c = powers[i]
            if j != i:
                c = (c + powers[j]) % k
            coeff.append(c)

        suffix = [0] * (m + 1)
        suffix[m] = 1  # residue zero
        for i in range(m - 1, -1, -1):
            mask = 0
            c = coeff[i]
            nxt = suffix[i + 1]
            for r in range(k):
                if (nxt >> r) & 1:
                    for d in range(10):
                        mask |= 1 << ((r + d * c) % k)
            suffix[i] = mask

        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            choices = range(9, 0, -1) if i == 0 else range(9, -1, -1)
            for d in choices:
                need = (-rem - d * c) % k
                if (suffix[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break
        return ''.join(digits + digits[:n // 2][::-1])

