from typing import List
from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nge = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            if st:
                nge[i] = st[-1]
            st.append(i)

        levels = n.bit_length()
        up = [array('I', nge)]
        sums = [array('q', (nums[i] * (nge[i] - i) for i in range(n)))]
        for _ in range(1, levels):
            pu, ps = up[-1], sums[-1]
            cu = array('I', [0]) * n
            cs = array('q', [0]) * n
            for i in range(n):
                mid = pu[i]
                cu[i] = pu[mid] if mid < n else n
                cs[i] = ps[i] + (ps[mid] if mid < n else 0)
            up.append(cu)
            sums.append(cs)

        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        def cost(l, r):
            cur = l
            total = 0
            for j in range(levels - 1, -1, -1):
                nxt = up[j][cur]
                if nxt <= r:
                    total += sums[j][cur]
                    cur = nxt
            total += (r - cur + 1) * nums[cur]
            return total - (pref[r + 1] - pref[l])

        ans = 0
        left = 0
        for r in range(n):
            if cost(left, r) > k:
