import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    vals = data[3:]
    values = vals[:n + m + l]
    total = len(values)
    full = (1 << total) - 1
    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n
    lower = []
    for x in values:
        mask = 0
        for i, y in enumerate(values):
            if y < x:
                mask |= 1 << i
        lower.append(mask)

    @lru_cache(None)
    def winning(hand_t, hand_a, turn):
        hand = hand_t if turn == 0 else hand_a
        if hand == 0:
            return False
        table = full ^ (hand_t | hand_a)
        remaining = hand
        while remaining:
            card = remaining & -remaining
            remaining -= card
            idx = card.bit_length() - 1
            if turn == 0:
                after_play_t, after_play_a = hand_t ^ card, hand_a
                next_turn = 1
            else:
                after_play_t, after_play_a = hand_t, hand_a ^ card
                next_turn = 0
            # The player may leave the played card on the table without taking one.
            if not winning(after_play_t, after_play_a, next_turn):
                return True
            candidates = table & lower[idx]
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                if turn == 0:
                    if not winning(after_play_t | taken, after_play_a, next_turn):
                        return True
                else:
                    if not winning(after_play_t, after_play_a | taken, next_turn):
                        return True
        return False

    print("Takahashi" if winning(initial_t, initial_a, 0) else "Aoki")

if __name__ == '__main__':
    main()

