class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        x = p.index('*')
        y = p.index('*', x + 1)
        A, B, C = p[:x], p[x + 1:y], p[y + 1:]
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        ao = occurrences(A)
        bo = occurrences(B)
        co = occurrences(C)

        if not B:
            if not A:
                return len(C) if (not C or co) else -1
            if not C:
                return len(A) if ao else -1
            answer = 10**9
            k = 0
            for a in ao:
                while k < len(co) and co[k] < a + len(A):
                    k += 1
                if k < len(co):
                    answer = min(answer, co[k] + len(C) - a)
            return answer if answer < 10**9 else -1

        answer = 10**9
        for b in bo:
            if A:
                k = bisect_right(ao, b - len(A)) - 1
                if k < 0:
                    continue
                a = ao[k]
            else:
                a = b

            if C:
                k = bisect_left(co, b + len(B))
                if k == len(co):
                    continue
                end = co[k] + len(C)
            else:
                end = b + len(B)

            answer = min(answer, end - a)

        return answer if answer < 10**9 else -1

