import sys

def solve_case(n, a, b):
    src = [i for i, c in enumerate(a) if c == '1']
    dst = [i for i, c in enumerate(b) if c == '1']
    if len(src) < len(dst):
        return -1
    if dst[-1] - dst[0] > src[-1] - src[0]:
        return -1
    # Ordered assignment: assign each target a consecutive nonempty group
    # of source pieces. Find the minimum possible maximum displacement.
    m, k = len(src), len(dst)
    lo, hi = 0, n
    def feasible(d):
        # Greedily match each target to one source within distance d;
        # all remaining sources must also be within d of some target.
        j = 0
        assigned = [0] * m
        for t in dst:
            while j < m and src[j] < t - d:
                j += 1
            if j == m or src[j] > t + d:
                return False
            assigned[j] = 1
            j += 1
        # Remaining sources may be grouped onto any target preserving order.
        # Check that each can be assigned to a neighboring target.
        for i, x in enumerate(src):
            if not assigned[i]:
                q = __import__('bisect').bisect_left(dst, x)
                if q == k or abs(dst[q] - x) > d:
                    if q == 0 or abs(dst[q-1] - x) > d:
                        return False
        return True
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid): hi = mid
        else: lo = mid + 1
    return lo

