class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        order = []
        stack = [(0, False)]
        while stack:
            u, done = stack.pop()
            if done:
                order.append(u)
            else:
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))

        pos = [0] * n
        size = [1] * n
        chars = []
        for i, u in enumerate(order):
            pos[u] = i
            chars.append(s[u])
            if parent[u] != -1:
                size[parent[u]] += size[u]
        t = ''.join(chars)

        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for u in range(n):
            end = pos[u]
            start = end - size[u] + 1
            length = size[u]
            if length % 2:
                center = (start + end) // 2
                answer[u] = odd[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[u] = even[center] >= length // 2
        return answer

