from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0
        reachable = [1] * n
        done = [x == 0 for x in nums]
        remaining = sum(not x for x in done)
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                reachable[i] |= reachable[i] << val
                if not done[i] and ((reachable[i] >> nums[i]) & 1):
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

