import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        prime = bytearray(b'\x01') * 10000
        prime[0:2] = b'\x00\x00'
        for p in range(2, 100):
            if prime[p]:
                start = p * p
                prime[start:10000:p] = b'\x00' * (((9999 - start) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        width = len(str(n))
        places = [10 ** i for i in range(width)]
        dist = {n: n}
        pq = [(n, n)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                min_digit = 1 if place == places[-1] else 0

                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist.get(y, float('inf')):
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))

                if digit > min_digit:
                    y = x - place
                    if not prime[y] and cost + y < dist.get(y, float('inf')):
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))

        return -1

