from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # z[i] is the LCP length of nums and nums[i:]
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # lcp[j] stores LCP(nums[i+1:], nums[j+1:]) on the previous row.
        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            first_ok = z[i] >= i
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    lcp[j] = lcp[j + 1] + 1
                else:
                    lcp[j] = 0
                if (first_ok and j >= 2 * i) or (j + (j - i) <= n and lcp[j] >= j - i):
                    answer += 1
        return answer

