from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        marked = [False] * n
        for i in targetIndices:
            marked[i] = True

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if marked[i] else 0
            # Descending order ensures dp[j - 1] is from the previous prefix.
            for j in range(m, 0, -1):
                best = dp[j] + cost  # remove this character, if allowed
                if ch == pattern[j - 1] and dp[j - 1] > best:
                    best = dp[j - 1]  # retain it to match the pattern
                dp[j] = best
            dp[0] += cost

        return dp[m]

