class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        ws = set()
        for a, b, w in edges:
            rev[b].append((a, w))
            ws.add(w)

        vals = sorted(ws)

        def ok(limit):
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        count += 1
                        stack.append(u)
            return count == n

        lo, hi = 0, len(vals) - 1
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if ok(vals[mid]):
                ans = vals[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

