        stacks = [[] for _ in range(26)]
        score = 0
        base = ord('a')
        for i, ch in enumerate(s):
            c = ord(ch) - base
            mirror = 25 - c
            if stacks[mirror]:
                j = stacks[mirror].pop()
                score += i - j
            else:
                stacks[c].append(i)
